/* Banco de preguntas - AMPLIACIÓN DE VARIEDAD (temas 1 a 10)
   Contenidos nuevos: comunicación, incendios, instrumental, lencería, escalas, salud mental,
   duelo, logística, farmacia, limpieza de material, transporte sanitario, ofimática, igualdad.
   B(...) = nivel normal · D(...) = nivel difícil (D está definida en preguntas-3.js). */

/* ================= TEMA 1 ================= */
B(1,"T","En el proceso de comunicación, el conjunto de signos y reglas compartidos por emisor y receptor con el que se elabora el mensaje es:","El código",["El canal","El contexto","El referente"],"El canal es el medio físico por el que circula el mensaje.");
D(1,"T","La barrera de la comunicación que se produce cuando emisor y receptor atribuyen significados distintos a las mismas palabras es una barrera:","Semántica",["Física","Fisiológica","Psicológica"],"Física: ruido, distancia. Fisiológica: sordera, afonía. Psicológica: prejuicios, emociones.");
B(1,"T","Decir con otras palabras lo que el interlocutor acaba de expresar, para comprobar que se le ha entendido, se denomina:","Parafrasear",["Interpretar","Aconsejar","Interrumpir"],"Es una de las técnicas básicas de la escucha activa.");
D(1,"T","El estilo de comunicación de quien no defiende sus derechos ni expresa sus opiniones para evitar el conflicto es el estilo:","Pasivo o inhibido",["Asertivo","Agresivo","Persuasivo"],"El asertivo defiende lo propio respetando al otro; el agresivo lo hace sin respetarlo.");
B(1,"T","La definición de salud como 'estado de completo bienestar físico, mental y social, y no solamente la ausencia de afecciones o enfermedades' corresponde a:","La Organización Mundial de la Salud",["La Ley General de Sanidad","La Constitución Española","El Estatuto Marco"],"Figura en el preámbulo de la Constitución de la OMS (1946, en vigor desde 1948).");
D(1,"T","En la teoría del fuego, el 'comburente' es:","El elemento que permite la combustión, normalmente el oxígeno del aire",["El material que arde","La fuente de calor que inicia el fuego","La reacción en cadena"],"Triángulo del fuego: combustible, comburente y calor. El tetraedro añade la reacción en cadena.");
D(1,"T","Los fuegos de combustibles líquidos, como la gasolina o el alcohol, son de clase:","B",["A","C","D"],"A: sólidos. B: líquidos. C: gases. D: metales. F: aceites y grasas de cocina.");
B(1,"T","Para apagar un fuego en un cuadro eléctrico en tensión, el extintor más adecuado es el de:","Dióxido de carbono (CO2)",["Agua pulverizada","Espuma física","Agua a chorro"],"El CO2 no conduce la electricidad ni deja residuos.");
D(1,"T","En la evacuación de un hospital, el traslado de los pacientes a un sector seguro de la misma planta se denomina:","Evacuación horizontal",["Evacuación vertical","Evacuación parcial diferida","Confinamiento"],"La vertical supone el traslado a otra planta o al exterior; se intenta primero la horizontal.");
B(1,"T","Durante una evacuación por incendio, los ascensores:","No deben utilizarse",["Deben utilizarse para los pacientes encamados","Solo puede usarlos el celador","Deben utilizarse para ir más rápido"],"Pueden quedar bloqueados o convertirse en chimenea de humos.");
B(1,"T","En las consultas externas, el celador:","Traslada documentación y pacientes y mantiene el orden en las salas de espera",["Toma las constantes a los pacientes","Cita a los pacientes para revisiones","Informa del resultado de las pruebas"],"Las tareas clínicas y administrativas corresponden a otros profesionales.");
D(1,"T","En el servicio de rehabilitación, el celador:","Ayuda a colocar y sujetar a los pacientes siguiendo las indicaciones del fisioterapeuta",["Aplica los tratamientos de electroterapia pautados","Realiza las movilizaciones pasivas terapéuticas","Decide la duración de los ejercicios"],"El tratamiento lo aplica el fisioterapeuta; el celador colabora en traslados y colocación.");
B(1,"T","La obligación de no revelar los datos que se conocen de los pacientes por razón del trabajo se denomina:","Secreto profesional o deber de confidencialidad",["Derecho de rectificación","Deber de información","Objeción de conciencia"],"Alcanza a todo el personal del centro, sanitario y no sanitario.");
D(1,"P","Un usuario muy enfadado se dirige al celador de información para quejarse a gritos de la espera. La respuesta más adecuada es:","Escucharle sin interrumpir, mostrar comprensión e informarle del cauce para presentar la reclamación",["Explicarle con firmeza que gritar no le dará la razón y pedirle que se marche","Darle la razón en todo y asegurarle que será atendido de inmediato","Ignorarle hasta que se calme y atender mientras tanto a otros usuarios"],"Escucha activa y asertividad: ni enfrentarse ni prometer lo que no depende de uno.");
D(1,"P","Se declara un incendio en una habitación de planta. El celador descubre el fuego. Tras dar la alarma, lo primero es:","Alejar del peligro a los pacientes en riesgo inmediato y cerrar la puerta de la habitación",["Abrir las ventanas para que salga el humo","Subir a la planta superior con los pacientes en el ascensor","Intentar apagarlo con agua aunque afecte a aparatos eléctricos"],"Cerrar puertas confina el fuego y el humo; abrir ventanas aviva la combustión.");
B(1,"P","Un celador de puerta observa que una persona fotografía a pacientes en la sala de espera. Debe:","Indicarle que no está permitido y avisar a su superior o a seguridad si persiste",["No intervenir, por ser un espacio público","Quitarle el teléfono","Pedir a los pacientes que se cubran la cara"],"La intimidad de los pacientes está protegida dentro del centro.");

/* ================= TEMA 2 ================= */
D(2,"T","El instrumento utilizado para explorar el conducto auditivo externo y el tímpano es el:","Otoscopio",["Oftalmoscopio","Rinoscopio","Laringoscopio"],"Oftalmoscopio: fondo de ojo. Rinoscopio: fosas nasales. Laringoscopio: laringe.");
D(2,"T","El instrumento utilizado para explorar el fondo de ojo es el:","Oftalmoscopio",["Otoscopio","Optotipo","Tonómetro"],"El optotipo es la tabla para medir la agudeza visual; el tonómetro mide la presión intraocular.");
B(2,"T","El balón autoinflable con mascarilla que se utiliza para ventilar manualmente a un paciente se conoce como:","Ambú o balón resucitador",["Ventimask","Caudalímetro","Aspirador de secreciones"],"La mascarilla tipo Venturi (Ventimask) administra oxígeno a concentración fija.");
D(2,"T","El dispositivo de oxigenoterapia que permite administrar una concentración de oxígeno fija y conocida es:","La mascarilla tipo Venturi",["Las gafas nasales","La mascarilla simple","El tubo de Guedel"],"El tubo de Guedel es una cánula orofaríngea que mantiene permeable la vía aérea.");
B(2,"T","El recipiente en forma de riñón que se utiliza para recoger vómitos o depositar pequeño material es:","La batea o riñonera",["La cuña","La botella","La copa graduada"],"La cuña y la botella se usan para la eliminación del paciente encamado.");
D(2,"T","Según la clasificación de Spaulding, la ropa de cama es un material:","No crítico",["Semicrítico","Crítico","Estéril"],"Entra en contacto con piel intacta.");
D(2,"T","Al retirar la ropa de cama sucia, lo correcto es:","Introducirla directamente en la bolsa del carro, sin sacudirla ni dejarla en el suelo",["Sacudirla para eliminar restos antes de embolsarla","Dejarla sobre la silla de la habitación hasta terminar","Apoyarla contra el uniforme para llevarla al carro"],"Sacudirla dispersa microorganismos; no debe tocar el suelo, otra cama ni el uniforme.");
B(2,"T","El carro de ropa sucia, mientras se hacen las camas, debe permanecer:","En el pasillo, a la puerta de la habitación",["Dentro de la habitación, junto a la cama","En el aseo del paciente","En el control de enfermería"],"No debe introducirse en las habitaciones para no vehicular microorganismos de una a otra.");
D(2,"T","El doblez que se hace en las esquinas de la ropa de cama para que quede ajustada se denomina:","Esquina de mitra o inglete",["Esquina de copete","Esquina de pliegue francés","Esquina de embozo"],"El embozo es la vuelta de la sábana encimera sobre la manta, en la cabecera.");
B(2,"T","La cama que tiene asignado un paciente que puede levantarse y en ese momento no está en ella es una cama:","Abierta desocupada",["Cerrada","Abierta ocupada","Quirúrgica"],"Abierta ocupada: con el paciente dentro. Cerrada: sin paciente asignado.");
D(2,"T","Cuando un paciente recibe el alta, tras la limpieza y preparación su cama pasa a ser una cama:","Cerrada",["Abierta desocupada","Abierta ocupada","Quirúrgica"],"La cama cerrada es la que espera un nuevo ingreso.");
B(2,"T","La mesa con ruedas y tablero regulable en altura que se coloca sobre la cama para que el paciente coma se denomina:","Mesa de cama o mesa auxiliar",["Mesilla de noche","Mesa de Mayo","Biombo"],"La mesa de Mayo es la mesa auxiliar de instrumental del quirófano.");
D(2,"T","La mesa auxiliar de altura regulable que en el quirófano se sitúa sobre el paciente para colocar el instrumental de uso inmediato es:","La mesa de Mayo",["La mesa de riñón","La mesa de cama","La mesa de curas"],"La mesa de riñón o de instrumental es la mesa grande auxiliar, con forma curva.");
B(2,"P","Al hacer una cama ocupada con la TCAE, el paciente no puede moverse. El celador:","Lo moviliza hacia un lado y después hacia el otro, sujetándolo, mientras se cambia la ropa por mitades",["Lo sienta en una silla, aunque tenga reposo absoluto","Hace la cama él solo mientras la TCAE atiende otras tareas","Levanta al paciente en brazos mientras se estira la sábana"],"Función 13ª: ayuda al movimiento de los encamados que requieran trato especial para hacerles la cama.");

/* ================= TEMA 3 ================= */
D(3,"T","La escala de Norton, utilizada para valorar el riesgo de úlceras por presión, puntúa cinco parámetros. Señale el que NO forma parte de ella:","Nutrición",["Estado mental","Incontinencia","Movilidad"],"Norton: estado físico general, estado mental, actividad, movilidad e incontinencia. La nutrición es un parámetro de la escala de Braden.");
D(3,"T","En la escala de Norton, una puntuación más baja indica:","Mayor riesgo de úlceras por presión",["Menor riesgo de úlceras por presión","Mayor grado de la úlcera ya instaurada","Mejor estado general del paciente"],"Oscila entre 5 (máximo riesgo) y 20 (mínimo riesgo).");
D(3,"T","La úlcera por presión en la que existe pérdida total del grosor de la piel, con afectación del tejido subcutáneo pero sin llegar a músculo ni hueso, es de:","Grado o categoría III",["Grado o categoría II","Grado o categoría IV","Grado o categoría I"],"I: eritema que no palidece. II: pérdida parcial, ampolla o abrasión. IV: afecta a músculo, hueso o estructuras de sostén.");
B(3,"T","La úlcera por presión que se manifiesta como un enrojecimiento de la piel intacta que no palidece al presionar es de:","Grado o categoría I",["Grado o categoría II","Grado o categoría III","Grado o categoría IV"],"Es la fase inicial y reversible si se alivia la presión.");
D(3,"T","La movilización en la que el paciente no colabora y el movimiento lo realiza íntegramente el profesional se denomina:","Movilización pasiva",["Movilización activa","Movilización activa asistida","Movilización resistida"],"En la activa asistida el paciente realiza parte del movimiento con ayuda.");
B(3,"T","Para movilizar a un paciente con la entremetida, esta debe abarcar aproximadamente:","Desde los hombros hasta los muslos",["Desde la cabeza hasta los pies","Desde la cintura hasta las rodillas","Solo la zona lumbar"],"Así sostiene el tronco y la pelvis, que concentran la mayor parte del peso.");
D(3,"T","Para sentar al borde de la cama a un paciente que colabora parcialmente, lo primero es colocar la cama:","En posición de Fowler",["En Trendelenburg","Totalmente horizontal y elevada al máximo","En antitrendelenburg"],"Con el tronco ya incorporado, se giran a la vez las piernas hacia fuera y el tronco hacia delante.");
B(3,"T","Al ayudar a un paciente a ponerse de pie desde el borde de la cama, el celador NO debe:","Tirar de él por las muñecas o por los brazos",["Bloquear con sus rodillas las del paciente","Sujetarlo por la cintura","Mantener la espalda recta"],"La tracción de los brazos puede lesionar el hombro, sobre todo en hemipléjicos.");
D(3,"T","Tras una intervención de columna, el cambio de postura del paciente debe hacerse:","En bloque, girando a la vez cabeza, tronco y pelvis",["De arriba abajo, girando primero los hombros y después la pelvis","Con el paciente sentado al borde de la cama","Tirando de la entremetida desde un solo lado"],"Se evita cualquier torsión del raquis.");
B(3,"T","Un miembro recién enyesado debe sostenerse durante la movilización:","Con las palmas de las manos, sin presionar con los dedos",["Con las puntas de los dedos, para no tocar el yeso","Por el extremo distal, dejando colgar el resto","Sin sujetarlo, dejándolo sobre la cama"],"La presión de los dedos puede dejar hundimientos en el yeso húmedo que luego comprimen la piel.");
D(3,"T","Al sentar en un sillón a un paciente hemipléjico, el brazo afectado debe quedar:","Apoyado sobre una almohada, en posición anatómica",["Colgando a lo largo del cuerpo","Recogido bajo el cuerpo del paciente","Sujeto con una venda al reposabrazos"],"Evita el edema y la subluxación del hombro.");
D(3,"T","La rotación habitual de los cambios posturales en un paciente encamado sin contraindicaciones es:","Decúbito supino, decúbito lateral derecho y decúbito lateral izquierdo, de forma alterna",["Decúbito supino, Trendelenburg y antitrendelenburg","Fowler, Roser y Sims, de forma alterna","Decúbito prono permanente con giros de cabeza"],"Se programan de forma individualizada, normalmente cada dos o tres horas.");
B(3,"T","La posición anatómica de referencia es aquella en la que el cuerpo está:","De pie, con la cabeza erguida, los brazos a lo largo del cuerpo y las palmas de las manos hacia delante",["De pie, con los brazos cruzados sobre el pecho","Tumbado boca arriba con las palmas hacia abajo","Sentado con las manos sobre las rodillas"],"Es la referencia para describir planos, ejes y movimientos.");
D(3,"T","En anatomía, el término 'distal' significa:","Más alejado de la raíz del miembro o del tronco",["Más cercano a la raíz del miembro o del tronco","Situado en la parte posterior","Situado hacia la línea media"],"Lo contrario es proximal. 'Hacia la línea media' es medial.");
D(3,"P","Hay que pasar de la cama a la camilla a un paciente consciente que no puede colaborar, y se dispone de un transfer. La camilla se coloca:","Paralela a la cama y pegada a ella, a la misma altura y con ambas frenadas",["Perpendicular a la cama, con la cabecera junto a los pies de la cama","Paralela a la cama, separada medio metro para que pase el celador","En ángulo, algo más alta que la cama para que el paciente resbale"],"La colocación perpendicular es la del traslado en brazos por tres personas, sin transfer.");
B(3,"P","Traslada en silla de ruedas a un paciente con suero, y la silla no tiene portasueros. Lo correcto es:","Llevar el suero en alto con la mano o pedir un portasueros, manteniéndolo por encima de la vía",["Colocar el suero sobre las piernas del paciente","Cerrar la llave y dejar el suero en la cama","Pedir al paciente que lo sostenga con la mano de la vía"],"Por debajo del punto de punción la sangre refluye por el sistema.");
D(3,"P","Un paciente con hemiplejia izquierda va a caminar con ayuda del celador. Este se colocará:","A su lado izquierdo, ligeramente por detrás",["A su lado derecho, ligeramente por delante","Delante de él, caminando de espaldas","A su lado derecho, sujetándole el brazo sano"],"El celador se sitúa del lado afectado, hacia donde es más probable la caída.");

/* ================= TEMA 4 ================= */
D(4,"T","La habitación destinada al aislamiento de un paciente con una enfermedad de transmisión aérea debe tener, respecto al pasillo, presión:","Negativa",["Positiva","Neutra","Positiva alterna"],"La presión positiva se usa en el aislamiento protector y en los quirófanos, para que no entre aire de fuera.");
B(4,"T","Las siglas UCI corresponden a:","Unidad de Cuidados Intensivos",["Unidad de Cirugía Inmediata","Unidad Central de Ingresos","Unidad de Control de Infecciones"],"También UVI: unidad de vigilancia intensiva.");
D(4,"T","El tejido recomendado para la ropa de quirófano, por no generar electricidad estática, es:","El algodón",["El nailon","La lana","El poliéster puro"],"Las fibras sintéticas y la lana acumulan cargas electrostáticas.");
D(4,"T","Dentro del equipo quirúrgico, quien se mueve por el quirófano fuera del campo estéril proporcionando el material que se necesita es:","La enfermera circulante",["La enfermera instrumentista","El primer ayudante","El celador"],"La instrumentista permanece estéril junto al cirujano.");
B(4,"T","El periodo que va desde que se decide la intervención hasta que el paciente entra en el quirófano se denomina:","Preoperatorio",["Intraoperatorio","Postoperatorio inmediato","Transoperatorio"],"Transoperatorio es sinónimo de intraoperatorio.");
D(4,"T","La cirugía que puede demorarse y se realiza en la fecha que se acuerda con el paciente se denomina:","Programada o electiva",["Urgente","Emergente","Paliativa"],"'Paliativa' clasifica la cirugía por su finalidad, no por el momento de realizarla.");
B(4,"T","La norma que estableció la plena integración de la salud mental en el sistema sanitario general fue:","La Ley 14/1986, General de Sanidad",["La Ley 41/2002, de autonomía del paciente","La Ley 55/2003, del Estatuto Marco","La Ley 31/1995, de prevención de riesgos"],"Su artículo 20 equipara al enfermo mental con las demás personas que requieren asistencia.");
D(4,"T","El dispositivo de salud mental al que el paciente acude durante el día para recibir tratamiento intensivo y regresa a su domicilio a dormir es:","El hospital de día",["La unidad de hospitalización psiquiátrica","El piso protegido","La unidad de larga estancia"],"La unidad de hospitalización psiquiátrica, o de agudos, es de internamiento breve en el hospital general.");
D(4,"T","Señale el elemento que NO forma parte del material homologado de contención mecánica:","Las vendas elásticas",["El cinturón abdominal","Las muñequeras y tobilleras","Los cierres magnéticos con su llave"],"No deben improvisarse sujeciones con vendas ni sábanas.");
B(4,"T","Una vez instaurada una contención mecánica, su retirada la decide:","El personal sanitario responsable",["El celador, cuando vea tranquilo al paciente","El familiar acompañante","El propio paciente"],"El celador nunca la retira por iniciativa propia.");
D(4,"T","En la unidad de hospitalización psiquiátrica, corresponde al celador:","Vigilar que los pacientes no tengan a su alcance objetos con los que puedan lesionarse",["Comprobar que los pacientes se han tomado la medicación","Decidir qué pacientes pueden salir al exterior","Dar de comer a los pacientes que se nieguen a hacerlo"],"El control de la toma de medicación y la alimentación son tareas de enfermería.");
D(4,"P","En el control de accesos del bloque quirúrgico se presenta un comercial de material médico que dice tener permiso del cirujano. El celador:","No le permite entrar sin la autorización establecida y lo consulta con la supervisión del bloque",["Le deja pasar si se pone gorro y calzas","Le deja pasar porque lo autoriza un facultativo de palabra","Le acompaña hasta la puerta del quirófano y espera con él"],"El acceso al área quirúrgica está restringido al personal autorizado.");
D(4,"P","Tiene que trasladar a planta a un paciente desde una habitación de aislamiento de contacto. Al salir de la habitación, el orden correcto es:","Retirarse primero los guantes, después la bata, y realizar higiene de manos",["Retirarse primero la bata, después los guantes, y lavarse las manos en el control","Salir con los guantes puestos para empujar la cama y quitárselos en el destino","Retirarse la bata y conservar los guantes hasta terminar el traslado"],"Los guantes, lo más contaminado, se retiran primero; siempre se termina con higiene de manos.");
B(4,"P","En una unidad de psiquiatría, un paciente pide al celador que le deje su mechero 'un momento'. El celador:","No se lo entrega y lo comunica al personal de enfermería",["Se lo deja y espera a que se lo devuelva","Se lo deja si promete fumar en el patio","Se lo entrega a otro paciente de confianza"],"Los objetos potencialmente peligrosos están controlados por el personal de la unidad.");

/* ================= TEMA 5 ================= */
D(5,"T","Según Kübler-Ross, el orden de las fases por las que pasa el enfermo terminal es:","Negación, ira, negociación, depresión y aceptación",["Negación, depresión, ira, negociación y aceptación","Ira, negación, negociación, aceptación y depresión","Negación, negociación, ira, depresión y aceptación"],"La negociación o pacto es la tercera fase.");
B(5,"T","Los cuidados que no buscan curar la enfermedad, sino aliviar los síntomas y procurar el mayor bienestar al enfermo y su familia, son los cuidados:","Paliativos",["Intensivos","Preventivos","Rehabilitadores"],"Atienden las necesidades físicas, psicológicas, sociales y espirituales.");
D(5,"T","Señale cuál de los siguientes es un signo TARDÍO de muerte:","Las livideces cadavéricas",["La ausencia de pulso","El cese de la respiración","La pérdida de la sensibilidad"],"Signos tardíos: enfriamiento, rigidez y livideces. Los demás son precoces.");
B(5,"T","La comunicación del fallecimiento a los familiares corresponde a:","El médico",["El celador","La TCAE","El personal de admisión"],"El celador no informa del fallecimiento ni de sus causas.");
B(5,"T","Señale el término que NO es sinónimo de fallecimiento:","Necropsia",["Óbito","Éxitus","Deceso"],"Necropsia es sinónimo de autopsia.");
D(5,"T","Durante el amortajamiento, las almohadas:","Se retiran, salvo una fina bajo la cabeza para evitar que se acumule sangre en la cara",["Se colocan todas bajo la cabeza para elevarla","Se colocan bajo los pies para vaciar las piernas","Se retiran todas y se baja la cabecera por debajo de la horizontal"],"Bajar la cabeza favorecería las livideces en el rostro.");
D(5,"T","Según el Real Decreto 2230/1982, en los hospitales autorizados se entiende que no hay oposición a la autopsia clínica si el cónyuge o los familiares en primer grado no la manifiestan dentro de las:","Cuatro horas siguientes a la entrega de la copia del certificado de muerte",["Veinticuatro horas siguientes al fallecimiento","Dos horas siguientes al fallecimiento","Doce horas siguientes a la entrega del certificado"],"Artículo 5 del Real Decreto 2230/1982.");
D(5,"T","Según el Real Decreto 2230/1982, la responsabilidad total del proceso de la autopsia clínica corresponde a:","El médico anatomopatólogo",["El médico que solicita la autopsia","El director del hospital","El médico forense"],"Puede delegar algunas fases, pero conserva la responsabilidad.");
D(5,"T","Según el Real Decreto 2230/1982, la realización de la autopsia clínica y los traslados de cadáveres que requiera:","No podrán suponer gasto alguno para la familia del fallecido",["Serán abonados por la familia según tarifa oficial","Serán a cargo de la familia solo si la solicita ella","Se costearán a partes iguales entre el hospital y la familia"],"El coste corre a cargo del presupuesto del hospital.");
D(5,"T","La autopsia clínica solo puede iniciarse después de que:","Un médico haya comprobado y certificado la muerte",["Hayan transcurrido veinticuatro horas desde la muerte","La familia haya contratado la funeraria","El juzgado haya expedido la licencia de enterramiento"],"Se extiende un certificado especial que solo acredita el fallecimiento.");
D(5,"T","Según el Decreto 129/2023, es obligatorio el embalsamamiento del cadáver cuando la inhumación o incineración no pueda realizarse antes de las:","96 horas tras el fallecimiento",["48 horas tras el fallecimiento","72 horas tras el fallecimiento","24 horas tras el fallecimiento"],"Entre las 48 y las 96 horas basta la conservación transitoria.");
B(5,"T","En la clasificación sanitaria del Decreto 129/2023, los cadáveres que no presentan riesgo infeccioso ni radiológico pertenecen al:","Grupo III",["Grupo I","Grupo II","Grupo 0"],"Grupo I: riesgo por enfermedad infecciosa. Grupo II: riesgo radiológico.");
D(5,"T","Señale la INCORRECTA sobre la autopsia judicial o médico-legal:","Requiere la autorización del cónyuge o de los familiares en primer grado",["La ordena la autoridad judicial","La practica el médico forense","Se realiza en muertes violentas o sospechosas de criminalidad"],"La oposición de la familia solo es relevante en la autopsia clínica.");
D(5,"P","Tras el fallecimiento de un paciente en planta, la enfermera pide ayuda al celador. Lo primero que debe haberse producido antes de iniciar los cuidados post mortem es:","La confirmación del fallecimiento por el médico",["La llegada del personal de la funeraria","La firma de la familia autorizando el amortajamiento","El transcurso de dos horas desde la muerte"],"Ningún cuidado post mortem se inicia sin la certificación médica de la muerte.");
B(5,"P","Al trasladar un cadáver al mortuorio, el celador encuentra el ascensor de uso interno ocupado y hay un ascensor de público libre. Debe:","Esperar al ascensor de uso interno",["Usar el de público para no demorarse","Usar el de público pidiendo a los visitantes que se aparten","Bajar el cadáver por la escalera con ayuda"],"El traslado se hace por circuitos internos, con discreción.");

/* ================= TEMA 6 ================= */
D(6,"T","El material que tiene una vida útil prolongada y figura en el registro de bienes del centro, como un monitor o una cama, es material:","Inventariable",["Fungible","Consumible","De reposición"],"El fungible se consume con el uso.");
D(6,"T","La retirada del almacén de los productos caducados, deteriorados u obsoletos se denomina:","Expurgo",["Inventario","Reposición","Rotación"],"Evita que lleguen a las unidades productos no aptos.");
D(6,"T","El sistema de gestión que busca disponer solo de la cantidad necesaria de producto en el momento en que se necesita, reduciendo al mínimo las existencias, es:","Just in time o justo a tiempo",["Stock de seguridad","Clasificación ABC","Sistema LIFO"],"Requiere proveedores muy fiables y entregas frecuentes.");
D(6,"T","El número de veces que se renuevan las existencias de un artículo en un periodo determinado se denomina:","Índice de rotación",["Punto de pedido","Stock medio","Lote económico"],"A mayor rotación, menos tiempo permanece el artículo almacenado.");
B(6,"T","El sistema de transporte que envía pequeños objetos, muestras o documentos entre servicios mediante cápsulas impulsadas por aire se denomina:","Tubo neumático",["Cinta transportadora","Montacargas","Carro autoguiado"],"Las muestras deben ir en envases adecuados y bien cerrados.");
D(6,"T","El documento mediante el cual una unidad de hospitalización solicita material al almacén del centro es:","El vale o pedido interno",["El albarán","La factura","La orden de compra"],"La orden de compra se dirige al proveedor externo.");
D(6,"T","La clasificación ABC de las existencias se basa en el principio de:","Pareto",["Arquímedes","Taylor","Maslow"],"Pocos artículos concentran la mayor parte del valor: regla aproximada del 80/20.");
B(6,"T","La zona del almacén destinada a la carga y descarga de los vehículos de transporte es:","El muelle",["La zona de picking","La zona de cuarentena","La zona de expurgo"],"Debe estar separada de las zonas asistenciales y del tránsito de pacientes.");
D(6,"T","Señale la INCORRECTA. Entre los criterios para ubicar los artículos en el almacén figura:","Colocar juntos los productos inflamables y los comburentes para ahorrar espacio",["Situar a mano los artículos de uso más frecuente","Tener en cuenta el tamaño y el peso de los artículos","Agrupar los artículos complementarios entre sí"],"Los productos incompatibles deben almacenarse separados.");
D(6,"T","Respecto a la compra de suministros, el celador de almacén:","No puede contratar ni comprar en ningún caso",["Puede comprar verbalmente si lo pide el médico de urgencias","Puede comprar si detecta en el inventario que se ha agotado un artículo","Puede comprar por orden verbal del jefe de la unidad"],"Debe comunicar el agotamiento a su superior; la compra corresponde al servicio de suministros.");
B(6,"T","El código formado por barras y espacios que identifica un producto y permite su lectura automática es:","El código de barras",["El número de lote","El número de registro sanitario","La fecha de caducidad"],"Facilita la gestión informatizada de entradas, salidas e inventarios.");
D(6,"T","El número que identifica al conjunto de unidades de un producto fabricadas en un mismo proceso, y que permite su retirada si se detecta un defecto, es:","El número de lote",["El código de barras","La referencia del proveedor","El número de albarán"],"Es la base de la trazabilidad del producto.");
D(6,"P","Sanidad ordena la retirada de un lote concreto de jeringas. Para localizarlas en el almacén, el celador debe fijarse en:","El número de lote impreso en el envase",["La fecha de recepción del pedido","El número del albarán","El color del embalaje"],"Solo el lote identifica las unidades afectadas.");
B(6,"P","Al preparar un pedido, el celador de almacén observa que no quedan existencias de un artículo solicitado. Debe:","Comunicarlo a su superior y anotar la falta en el pedido",["Sustituirlo por otro parecido sin avisar","Comprarlo en una farmacia cercana","Entregar el pedido sin decir nada"],"Notificar el agotamiento de existencias es una de sus funciones.");

/* ================= TEMA 7 ================= */
D(7,"T","La responsabilidad del servicio de farmacia hospitalaria corresponde a:","Un farmacéutico especialista en farmacia hospitalaria",["Un médico especialista en farmacología clínica","El director de enfermería","Un técnico superior en farmacia"],"Es un servicio general clínico, o central, del hospital.");
D(7,"T","La actividad de salud pública que identifica, cuantifica y evalúa los riesgos asociados al uso de los medicamentos ya comercializados se denomina:","Farmacovigilancia",["Farmacocinética","Farmacotecnia","Farmacoeconomía"],"La farmacotecnia es la elaboración de medicamentos.");
D(7,"T","La sustancia de un medicamento a la que se debe su efecto terapéutico se denomina:","Principio activo",["Excipiente","Forma farmacéutica","Placebo"],"El excipiente es la sustancia sin actividad que acompaña al principio activo y le da forma.");
D(7,"T","La vía de administración en la que el medicamento se deposita debajo de la lengua para su absorción es la vía:","Sublingual",["Oral","Tópica","Subcutánea"],"En la vía oral el medicamento se traga y se absorbe en el tubo digestivo.");
D(7,"T","Señale la vía de administración que NO es parenteral:","Rectal",["Intramuscular","Subcutánea","Intravenosa"],"Parenteral: la que atraviesa la piel mediante inyección.");
B(7,"T","Las siglas EFG en el envase de un medicamento significan:","Equivalente farmacéutico genérico",["Especialidad farmacéutica garantizada","Envase farmacéutico general","Excipiente de fórmula galénica"],"Identifican a los medicamentos genéricos.");
D(7,"T","Si un celador de farmacia recibe de una planta la petición urgente de un medicamento, debe:","Pasar la petición al farmacéutico responsable",["Entregarlo él mismo si conoce su ubicación","Entregarlo si la petición viene firmada por una enfermera","Indicar a la planta que lo compre en una farmacia"],"El celador traslada, pero no dispensa.");
D(7,"T","En la limpieza manual del instrumental, la secuencia correcta es:","Lavado, aclarado y secado",["Aclarado, lavado y secado","Lavado, secado y aclarado","Secado, lavado y aclarado"],"El secado final es imprescindible: la humedad interfiere en la esterilización.");
D(7,"T","El sistema de limpieza mecánica especialmente indicado para instrumental con zonas de difícil acceso es:","La cubeta de ultrasonidos",["El cepillo metálico","El autoclave","La estufa de calor seco"],"No deben usarse cepillos ni estropajos metálicos, que dañan el instrumental.");
B(7,"T","El material nuevo, antes de su primera esterilización, debe:","Limpiarse igualmente",["Esterilizarse directamente, sin limpiar","Sumergirse en lejía concentrada","Engrasarse con aceite industrial"],"Puede traer restos de fabricación, polvo o grasa.");
D(7,"T","El envoltorio de esterilización que tiene una cara de papel y otra de film plástico transparente se denomina:","Bolsa mixta o papel mixto",["Papel crepado","Contenedor rígido","Tejido sin tejer"],"El papel crepado es opaco por ambas caras y se usa para envolver paquetes.");
D(7,"T","La prueba de Bowie-Dick es un control:","Del equipo, que se realiza a diario con el autoclave vacío",["De la carga, que se introduce en cada paquete","Biológico, que utiliza esporas","Del envasado, que comprueba el sellado de las bolsas"],"Comprueba la eliminación del aire y la penetración del vapor en autoclaves de prevacío.");
D(7,"T","Para quitar el pijama a un paciente encamado que tiene un suero en un brazo, se saca primero la manga:","Del brazo libre",["Del brazo con el suero","De cualquiera, cerrando antes la llave","De ambos brazos a la vez"],"Para vestirlo se hace al revés: primero el brazo con el suero.");
B(7,"T","El aseo del paciente que no puede levantarse de la cama se realiza:","Diariamente y cuantas veces sea necesario",["Cada tres días","Solo cuando lo pida el paciente","Una vez por semana"],"Mantiene la integridad de la piel y el bienestar del paciente.");
D(7,"T","Según la Ley 41/2002, el conjunto de documentos que contienen los datos, valoraciones e informaciones sobre la situación y la evolución clínica de un paciente a lo largo del proceso asistencial es:","La historia clínica",["La documentación clínica","El informe de alta médica","El certificado médico"],"La 'documentación clínica' es el soporte de cualquier tipo que contiene datos asistenciales.");
D(7,"T","Según la Ley 41/2002, los centros sanitarios deben conservar la documentación clínica, como mínimo:","Cinco años contados desde la fecha del alta de cada proceso asistencial",["Cinco años contados desde la fecha del ingreso","Diez años contados desde el fallecimiento del paciente","Indefinidamente en todos los casos"],"Artículo 17.1 de la Ley 41/2002.");
B(7,"T","La función de la fotocopiadora que entrega varios juegos de copias ya ordenados por páginas se denomina:","Clasificar o intercalar",["Dúplex","Zoom","Escanear"],"Dúplex es la copia a doble cara.");
D(7,"T","La encuadernación que une las hojas mediante una pieza de plástico cilíndrica con dientes que se introducen en perforaciones rectangulares es la de:","Canutillo",["Espiral metálica","Térmica","Grapado en caballete"],"La de espiral utiliza un alambre continuo en perforaciones redondas; la térmica, cola caliente.");
D(7,"P","Un celador traslada el carro de unidosis a una planta y un paciente le pide en el pasillo 'la pastilla de las doce, que está en mi cajetín'. El celador:","No se la entrega y avisa a la enfermera de la unidad",["Se la entrega, porque el cajetín lleva su nombre","Se la entrega si un familiar confirma la pauta","Le indica que la coja él mismo del carro"],"La administración de medicación corresponde a enfermería.");
D(7,"P","En el almacén de sueros de farmacia, el celador encuentra una caja con el contenido derramado. Debe:","Comunicarlo al personal responsable, sin retirar ni manipular el producto por su cuenta",["Tirar la caja y limpiar la zona sin avisar","Recolocar los envases intactos en otra caja","Repartir los envases sanos entre las plantas"],"Puede tratarse de un producto que requiera precauciones o del que haya que dejar constancia.");
B(7,"P","Le encargan 30 copias de un documento de 10 páginas, grapadas por juegos. La forma más eficiente de programar la fotocopiadora es:","Seleccionar 30 copias con la función de clasificar y grapar",["Hacer 30 copias de cada página y ordenarlas a mano","Copiar el documento completo 30 veces, una a una","Reducir el documento para que quepa en menos hojas"],"La función de clasificado entrega cada juego ordenado.");

/* ================= TEMA 8 ================= */
D(8,"T","La palabra 'triaje' procede del francés 'trier', que significa:","Clasificar o escoger",["Curar o atender","Trasladar o evacuar","Esperar o demorar"],"Clasifica a los pacientes por gravedad para priorizar su atención.");
B(8,"T","Señale cuál de las siguientes NO es un área propia del servicio de urgencias hospitalario:","Rehabilitación",["Triaje","Boxes de exploración","Observación"],"También forman parte admisión, sala de espera y sala de críticos o de emergencias.");
D(8,"T","El transporte sanitario que se realiza dentro del propio hospital, entre servicios, se denomina:","Terciario o intrahospitalario",["Secundario o interhospitalario","Primario","Programado colectivo"],"El secundario se realiza entre dos centros sanitarios distintos.");
D(8,"T","En la parte delantera de las ambulancias, la palabra 'AMBULANCIA' figura escrita en sentido inverso para:","Que pueda leerse por reflexión en el retrovisor del vehículo que circula delante",["Distinguir las ambulancias asistenciales de las no asistenciales","Cumplir una norma de rotulación de vehículos oficiales","Que no se confunda con los vehículos policiales"],"Detrás y en los laterales figura en sentido normal.");
D(8,"T","Según el Real Decreto 836/2012, las ambulancias no asistenciales de clase A1 deben contar al menos con:","Un conductor con, como mínimo, el certificado de profesionalidad de transporte sanitario y, cuando el servicio lo requiera, un ayudante con la misma cualificación",["Un conductor con el título de técnico en emergencias sanitarias y un enfermero","Un conductor con permiso de conducción, sin otra cualificación","Dos técnicos en emergencias sanitarias y un médico"],"El título de técnico en emergencias sanitarias se exige en las asistenciales B y C.");
D(8,"T","El dispositivo que, al extraerle el aire, se adapta al cuerpo del paciente y lo inmoviliza por completo para el traslado es:","El colchón de vacío",["La camilla de cuchara","El tablero espinal","El collarín cervical"],"La camilla de cuchara sirve para recoger al paciente, no para trasladarlo largas distancias.");
D(8,"T","El dispositivo tipo chaleco que inmoviliza cabeza, cuello y tronco para extraer a un accidentado de un vehículo es:","El dispositivo de extricación tipo Kendrick",["El colchón de vacío","La férula de tracción","La camilla nido"],"También conocido como férula espinal o corsé de extricación.");
B(8,"T","El dispositivo que se utiliza para inmovilizar una extremidad fracturada es:","La férula",["El collarín","El torniquete","El tubo de Guedel"],"Puede ser rígida, hinchable o de vacío.");
D(8,"T","En la RCP básica de un niño realizada por personal sanitario, la relación compresiones-ventilaciones recomendada es:","15 compresiones y 2 ventilaciones, tras cinco ventilaciones iniciales",["30 compresiones y 2 ventilaciones, sin ventilaciones iniciales","5 compresiones y 1 ventilación","15 compresiones y 5 ventilaciones"],"En el adulto es 30:2 y se comienza por las compresiones.");
D(8,"T","Las siglas DEA corresponden a:","Desfibrilador externo automático",["Dispositivo de emergencia avanzada","Desfibrilador eléctrico de alta energía","Dispositivo externo de aspiración"],"El DESA es semiautomático: analiza el ritmo y el reanimador pulsa el botón de descarga.");
B(8,"T","Ante una hemorragia externa, la primera medida es:","La presión directa sobre el punto sangrante",["El torniquete","La elevación de las piernas","La aplicación de calor local"],"El torniquete se reserva para hemorragias graves que no ceden con presión.");
D(8,"T","En el traslado de un paciente en situación de shock sin otra contraindicación, la posición indicada es:","Decúbito supino con las piernas elevadas, o Trendelenburg",["Fowler alta","Decúbito prono","Antitrendelenburg"],"Favorece el retorno venoso hacia los órganos vitales.");
B(8,"T","En Galicia, la gestión de las urgencias y emergencias sanitarias extrahospitalarias corresponde a:","La Fundación Pública Urxencias Sanitarias de Galicia-061",["El servicio de protección civil municipal","El Instituto Nacional de Gestión Sanitaria","La Axencia Galega de Emerxencias exclusivamente"],"Su central de coordinación atiende el teléfono 061.");
D(8,"T","Al llevar a un paciente de urgencias a una planta de hospitalización, el celador:","Ayuda a encamarlo, entrega la documentación al personal de la unidad y regresa a urgencias",["Lo deja en el pasillo de la planta y regresa a urgencias","Permanece en la planta hasta que el médico pase visita","Entrega la documentación a la familia para que la guarde"],"El paciente y su documentación se entregan siempre al personal de la unidad de destino.");
D(8,"P","Un coche se detiene ante la puerta de urgencias y el conductor grita que su acompañante ha perdido el conocimiento. El celador:","Avisa de inmediato al personal sanitario y acude con una camilla, sin sacar al paciente bruscamente",["Lo saca tirando de los brazos y lo sienta en una silla de ruedas","Pide al conductor que aparque y pase por admisión","Espera a que salga el médico antes de acercarse"],"Un paciente inconsciente se traslada en camilla; puede haber lesiones que la tracción agrave.");
D(8,"P","En urgencias hay que pasar a la camilla de exploración a un paciente con sospecha de fractura de cadera. El celador:","Lo moviliza con ayuda, en bloque, manteniendo alineada la extremidad y sin flexionar la cadera",["Le pide que se incorpore y pase él mismo apoyando la pierna sana","Lo gira sobre el lado lesionado para deslizarlo","Lo sienta primero al borde de la camilla con las piernas colgando"],"Debe evitarse cualquier rotación o flexión de la extremidad afectada.");
B(8,"P","Un paciente en la sala de espera de urgencias le dice al celador que su dolor ha aumentado mucho desde que fue clasificado. El celador:","Lo comunica de inmediato al personal de enfermería de triaje",["Le dice que debe esperar su turno","Lo pasa él mismo a un box libre","Le ofrece un analgésico de su taquilla"],"El triaje es dinámico: un empeoramiento obliga a reevaluar la prioridad.");

/* ================= TEMA 9 ================= */
B(9,"T","La red que conecta los ordenadores de un mismo edificio o departamento para compartir recursos como una impresora es una red:","LAN",["WAN","MAN","VPN"],"LAN: red de área local. WAN: red de área extensa.");
B(9,"T","Un archivo con extensión .jpg contiene normalmente:","Una imagen",["Un vídeo","Un documento de texto","Una hoja de cálculo"],"Otras extensiones de imagen: .png, .gif, .bmp.");
D(9,"T","Un gigabyte equivale a:","1024 megabytes",["1024 kilobytes","1000 kilobytes","1024 terabytes"],"1 terabyte son 1024 gigabytes.");
D(9,"T","En una hoja de cálculo, de forma predeterminada:","Las filas se identifican con números y las columnas con letras",["Las filas se identifican con letras y las columnas con números","Filas y columnas se identifican con números","Filas y columnas se identifican con letras"],"Por eso la celda B3 está en la columna B y la fila 3.");
D(9,"T","En Excel, un archivo completo, que puede contener varias hojas, se denomina:","Libro",["Hoja","Rango","Tabla dinámica"],"Cada libro contiene una o más hojas de cálculo.");
B(9,"T","El programa diseñado para almacenar gran cantidad de datos relacionados entre sí y consultarlos de forma organizada es:","Un gestor de bases de datos",["Un procesador de textos","Un navegador","Un cliente de correo"],"Por ejemplo, Microsoft Access o LibreOffice Base.");
D(9,"T","Señale la INCORRECTA:","Google Chrome es un buscador y Google es un navegador",["Mozilla Firefox es un navegador","Bing es un buscador","Microsoft Edge es un navegador"],"Es al revés: Chrome es el navegador y Google el buscador.");
B(9,"T","En un programa de correo, los mensajes recibidos se almacenan en:","La bandeja de entrada",["La bandeja de salida","La carpeta de borradores","La carpeta de enviados"],"En borradores quedan los mensajes redactados y aún no enviados.");
D(9,"T","En un procesador de textos, las distintas tipografías disponibles (Arial, Times New Roman, Calibri) se denominan:","Fuentes",["Estilos","Plantillas","Formatos de párrafo"],"El estilo es un conjunto de formatos guardado con un nombre.");
D(9,"T","La tarjeta gráfica de un ordenador es:","Un componente de hardware",["Un programa de retoque fotográfico","Un tipo de sistema operativo","Un periférico de entrada"],"El software es la parte lógica: los programas.");
B(9,"T","La extensión .pdf corresponde a:","Un documento de formato portátil, que se ve igual en cualquier dispositivo",["Una presentación de diapositivas","Un archivo de audio comprimido","Un archivo ejecutable"],"Se abre con un lector de PDF o con el navegador.");
D(9,"T","La copia de los datos que se guarda en otro soporte para poder recuperarlos en caso de pérdida se denomina:","Copia de seguridad o backup",["Formateo","Desfragmentación","Compresión"],"Debe conservarse en un soporte distinto del original.");
D(9,"P","En Word debe mover un párrafo de la página 1 a la página 3, sin que quede en su posición original. La secuencia correcta es:","Seleccionar, Ctrl + X, situar el cursor en el destino y Ctrl + V",["Seleccionar, Ctrl + C, situar el cursor en el destino y Ctrl + V","Seleccionar, Ctrl + V, situar el cursor en el destino y Ctrl + X","Seleccionar, Ctrl + Z, situar el cursor en el destino y Ctrl + V"],"Ctrl + X corta; Ctrl + C dejaría una copia en el origen.");

/* ================= TEMA 10 ================= */
D(10,"T","La concentración de mujeres en determinados sectores y profesiones, tradicionalmente considerados femeninos, se denomina:","Segregación horizontal",["Segregación vertical","Techo de cristal","Brecha salarial"],"La vertical es la concentración en los niveles inferiores de la jerarquía.");
D(10,"T","El reparto equilibrado entre mujeres y hombres de las tareas domésticas y de cuidado se denomina:","Corresponsabilidad",["Conciliación","Coeducación","Paridad"],"La conciliación es la posibilidad de compatibilizar la vida personal, familiar y laboral.");
D(10,"T","Las ideas preconcebidas y simplificadas sobre cómo son y cómo deben comportarse mujeres y hombres se denominan:","Estereotipos de género",["Roles de género","Identidades de género","Acciones positivas"],"Los roles son las tareas y funciones que la sociedad asigna a cada sexo.");
D(10,"T","Las medidas específicas y temporales en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres son:","Acciones positivas",["Discriminaciones directas","Medidas de conciliación","Cuotas permanentes"],"Artículo 11 de la Ley Orgánica 3/2007: deben ser razonables y proporcionadas.");
B(10,"T","El proceso por el que las mujeres adquieren mayor control sobre sus vidas y participan en la toma de decisiones se denomina:","Empoderamiento",["Transversalidad","Coeducación","Feminización"],"Término consolidado en la Conferencia Mundial sobre la Mujer de Pekín (1995).");
D(10,"T","Los Juzgados de Violencia sobre la Mujer fueron creados por:","La Ley Orgánica 1/2004, de 28 de diciembre",["La Ley Orgánica 3/2007, de 22 de marzo","La Ley 27/2003, de 31 de julio","La Ley gallega 11/2007, de 27 de julio"],"La Ley 27/2003 reguló la orden de protección de las víctimas de violencia doméstica.");
D(10,"T","La orden de protección de las víctimas de la violencia doméstica fue regulada por:","La Ley 27/2003, de 31 de julio",["La Ley Orgánica 1/2004, de 28 de diciembre","La Ley Orgánica 3/2007, de 22 de marzo","La Ley 41/2002, de 14 de noviembre"],"Unifica en una resolución judicial medidas penales, civiles y asistenciales.");
B(10,"T","En Galicia, el teléfono gratuito de información a las mujeres, que funciona las 24 horas, es el:","900 400 273",["900 116 016","902 400 116","012"],"El 900 116 016 es el del 016 para personas con discapacidad auditiva.");
D(10,"T","Según la guía técnica del Servizo Galego de Saúde sobre atención a mujeres en situación de violencia de género, ante la sospecha de maltrato la entrevista debe hacerse:","A solas con la mujer, garantizando la confidencialidad",["En presencia de su pareja, para contrastar las versiones","Con un familiar que pueda confirmar los hechos","Delante de otros pacientes, para que se sienta acompañada"],"La presencia del posible agresor impide que la mujer hable y aumenta su riesgo.");
D(10,"T","Según esa misma guía del Servizo Galego de Saúde, ante una mujer que reconoce sufrir maltrato NO debe hacerse:","Recomendar terapia de pareja o mediación familiar",["Creer su relato y escucharla","Hacerle sentir que no es culpable","Informarla de los recursos disponibles"],"Tampoco criticarla, minimizar el peligro ni imponerle decisiones.");
D(10,"T","Es un indicador de sospecha de maltrato relacionado con la actitud de la pareja:","Que solicite estar presente en toda la visita y responda por ella",["Que espere fuera de la consulta","Que pregunte por los horarios de visita","Que pida un justificante de acompañamiento"],"Otros: actitud controladora u hostil, o excesiva solicitud.");
D(10,"T","Ante una agresión sexual reciente, para no perder pruebas debe recomendarse a la víctima que, antes de la exploración:","No se lave ni se cambie de ropa",["Se duche con agua caliente","Se cambie de ropa y tire la que llevaba","Coma y beba para reponerse"],"La toma de muestras se realiza con intervención forense y cadena de custodia.");
D(10,"T","Las fotografías de las lesiones de una mujer víctima de violencia de género solo pueden tomarse:","Con su autorización por escrito",["Con la autorización verbal del médico","Cuando lo pida la policía","Sin autorización, si es para la historia clínica"],"Así lo recoge la guía técnica del Servizo Galego de Saúde.");
B(10,"T","El tratado internacional del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica se conoce como:","Convenio de Estambul",["Convenio de Oviedo","Declaración de Pekín","Carta de Ottawa"],"Se abrió a la firma en 2011. El de Oviedo trata de derechos humanos y biomedicina.");
D(10,"P","Una paciente ingresada cuenta al celador que su marido le controla el dinero, le prohíbe ver a su familia y la insulta, pero que 'nunca le ha pegado'. Esa situación:","Constituye violencia de género de tipo psicológico y económico, y debe comunicarse al personal sanitario",["No es violencia de género, al no existir agresión física","Es un conflicto de pareja que no corresponde al ámbito sanitario","Solo sería violencia de género si existiera denuncia previa"],"La violencia no es solo física; el aislamiento, el control y la humillación son formas de maltrato.");
D(10,"P","Una mujer que ha sufrido una agresión sexual llega a urgencias y pide al celador ir al aseo a lavarse antes de que la atiendan. Lo adecuado es:","Explicarle con delicadeza que es mejor esperar y avisar de inmediato al personal sanitario",["Acompañarla al aseo y facilitarle toallas","Indicarle que primero pase por admisión","Darle ropa limpia del hospital para que se cambie"],"Lavarse o cambiarse de ropa puede eliminar pruebas; la prioridad es la atención sanitaria inmediata.");
